import React from "react";

function JobStats({ jobs }) {
  const styles = {
    statsGrid: {
      display: "flex",
      flexWrap: "wrap",
      gap: "20px",
      marginBottom: "20px",
    },
    statsCard: {
      backgroundColor: "#fff",
      borderRadius: "8px",
      boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
      padding: "20px",
      flex: "1 1 calc(33.333% - 20px)",
      display: "flex",
      flexDirection: "column",
      alignItems: "flex-start",
      minWidth: "200px",
    },
    statsLabel: {
      fontSize: "0.875rem",
      color: "#6b7280", // gray-500
      marginBottom: "5px",
    },
    statsNumber: {
      fontSize: "2rem",
      fontWeight: "bold",
      color: "#111827", // gray-900
    },
    // Media query workaround for inline styles
    '@media (max-width: 768px)': {
      statsCard: {
        flex: "1 1 100%",
      },
    },
  };

  return (
    <div style={styles.statsGrid}>
      <div style={styles.statsCard}>
        <div style={styles.statsLabel}>Total Jobs</div>
        <div style={styles.statsNumber}>{jobs.length}</div>
      </div>
      <div style={styles.statsCard}>
        <div style={styles.statsLabel}>Full-time Positions</div>
        <div style={styles.statsNumber}>
          {jobs.filter((j) => j.jobType === "Full-time").length}
        </div>
      </div>
      <div style={styles.statsCard}>
        <div style={styles.statsLabel}>Part-time Positions</div>
        <div style={styles.statsNumber}>
          {jobs.filter((j) => j.jobType === "Part-time").length}
        </div>
      </div>
    </div>
  );
}

export default JobStats;
